import React from 'react';
import { render, screen } from '@testing-library/react';
import { Grid } from '../..';

describe('Grid', () => {
  it('should render without crashing', () => {
    render(
      <Grid.Container>
        <Grid.Item>
          <h1>Grid</h1>
        </Grid.Item>
      </Grid.Container>
    );
    expect(screen.getByText('Grid')).toBeInTheDocument();
  });
  it('should render with sidebar padding without crashing', () => {
    render(
      <Grid.Container sidebar type="fluid">
        <Grid.Item xs={12}>
          <h1>Grid</h1>
        </Grid.Item>
      </Grid.Container>
    );
    expect(screen.getByText('Grid')).toBeInTheDocument();
  });
});
